function expect(val: unknown) {
  return {
    toBe(other: unknown): true {
      if (val !== other) throw new Error("Not Equal");
      return true;
    },
    notToBe(other: unknown): true {
      if (val === other) throw new Error("Equal");
      return true;
    },
  };
}

function runMatcher(val: unknown, matcher: string, other: unknown): string {
  try {
    expect(val)[matcher as "toBe" | "notToBe"](other);
    return "pass";
  } catch (err) {
    return (err as Error).message;
  }
}

