class Solution:
    def expect(self, val):
        # strict equality: same type and same value (so 1 is not True)
        def same(other):
            return type(val) is type(other) and val == other

        class Matchers:
            def toBe(self, other):
                if not same(other):
                    raise ValueError("Not Equal")
                return True

            def notToBe(self, other):
                if same(other):
                    raise ValueError("Equal")
                return True

        return Matchers()

    def runMatcher(self, val, matcher: str, other) -> str:
        try:
            getattr(self.expect(val), matcher)(other)
            return "pass"
        except ValueError as err:
            return str(err)

